SirExpressionOpInterface AstToSir::VisitExpression(mlir::OpBuilder &builder, const SExpression *node) {
  if (auto *identifier = dynamic_cast<const SIdentifier *>(node)) {
    return VisitIdentifier(builder, identifier);
  }
  if (auto *call = dynamic_cast<const SCall *>(node)) {
    return VisitCall(builder, call);
  }
  if (auto *member = dynamic_cast<const SMember *>(node)) {
    return VisitMember(builder, member);
  }
  if (auto *paren = dynamic_cast<const SParen *>(node)) {
    return VisitParen(builder, paren);
  }
  LOG(FATAL) << "Unreachable code.";
}

SirPatternRefOpInterface AstToSir::VisitPatternRef(mlir::OpBuilder &builder, const SPattern *node) {
  if (auto *identifier = dynamic_cast<const SIdentifier *>(node)) {
    return VisitIdentifierRef(builder, identifier);
  }
  if (auto *paren = dynamic_cast<const SParen *>(node)) {
    return VisitParenRef(builder, paren);
  }
  LOG(FATAL) << "Unreachable code.";
}

SirStatementOpInterface AstToSir::VisitStatement(mlir::OpBuilder &builder, const SStatement *node) {
  if (auto *declaration = dynamic_cast<const SDeclaration *>(node)) {
    return VisitDeclaration(builder, declaration);
  }
  if (auto *expression_statement = dynamic_cast<const SExpressionStatement *>(node)) {
    return VisitExpressionStatement(builder, expression_statement);
  }
  if (auto *loop = dynamic_cast<const SLoop *>(node)) {
    return VisitLoop(builder, loop);
  }
  LOG(FATAL) << "Unreachable code.";
}

SirIdentifierOp AstToSir::VisitIdentifier(mlir::OpBuilder &builder, const SIdentifier *node) {
  mlir::StringAttr mlir_name = builder.getStringAttr(node->name());
  return CreateExpr<SirIdentifierOp>(builder, node, mlir_name);
}

SirIdentifierRefOp AstToSir::VisitIdentifierRef(mlir::OpBuilder &builder, const SIdentifier *node) {
  mlir::StringAttr mlir_name = builder.getStringAttr(node->name());
  return CreateExpr<SirIdentifierRefOp>(builder, node, mlir_name);
}

SirCallOp AstToSir::VisitCall(mlir::OpBuilder &builder, const SCall *node) {
  mlir::Value mlir_callee = VisitExpression(builder, node->callee());
  return CreateExpr<SirCallOp>(builder, node, mlir_callee);
}

SirDeclarationOp AstToSir::VisitDeclaration(mlir::OpBuilder &builder, const SDeclaration *node) {
  SirIdentifierAttr mlir_id = VisitIdentifierAttr(builder, node->id());
  return CreateStmt<SirDeclarationOp>(builder, node, mlir_id);
}

SirExpressionStatementOp AstToSir::VisitExpressionStatement(mlir::OpBuilder &builder, const SExpressionStatement *node) {
  mlir::Value mlir_expression = VisitExpression(builder, node->expression());
  return CreateStmt<SirExpressionStatementOp>(builder, node, mlir_expression);
}

SirMemberOp AstToSir::VisitMember(mlir::OpBuilder &builder, const SMember *node) {
  mlir::Value mlir_object = VisitExpression(builder, node->object());
  mlir::Attribute mlir_literal_property;
  mlir::Value mlir_computed_property;
  if (!node->computed()) {
    if (const auto *property_identifier = dynamic_cast<const SIdentifier *>(node->property())) {
      mlir_literal_property = VisitIdentifierAttr(builder, property_identifier);
    } else {
      LOG(FATAL) << "If computed is false, property must be Identifier.";
    }
  } else {
    mlir_computed_property = VisitExpression(builder, node->property());
  }
  return CreateExpr<SirMemberOp>(builder, node, mlir_object, mlir_literal_property, mlir_computed_property);
}

SirPropertyOp AstToSir::VisitProperty(mlir::OpBuilder &builder, const SProperty *node) {
  const SExpression *value_ir = std::visit([](const auto *value) { return dynamic_cast<const SExpression *>(value); }, node->value());
  CHECK(value_ir != nullptr) << "value must be a SExpression.";
  mlir::Value mlir_value = VisitExpression(builder, value_ir);
  return CreateExpr<SirPropertyOp>(builder, node, mlir_value);
}

SirPropertyRefOp AstToSir::VisitPropertyRef(mlir::OpBuilder &builder, const SProperty *node) {
  const SPattern *value_ir = std::visit([](const auto *value) { return dynamic_cast<const SPattern *>(value); }, node->value());
  CHECK(value_ir != nullptr) << "value must be a SPattern.";
  mlir::Value mlir_value = VisitPatternRef(builder, value_ir);
  return CreateExpr<SirPropertyRefOp>(builder, node, mlir_value);
}

SirLoopOp AstToSir::VisitLoop(mlir::OpBuilder &builder, const SLoop *node) {
  mlir::Value mlir_left_pattern;
  switch (node->left().index()) {
    case 1: {
      mlir_left_pattern = VisitPatternRef(builder, std::get<1>(node->left()));
      break;
    }
    default:
      break;
  }
  auto op = CreateStmt<SirLoopOp>(builder, node, mlir_left_pattern);
  if (node->init().has_value()) {
    switch (node->init().value().index()) {
      case 0: {
        mlir::Region &mlir_init_declaration_region = op.getInitDeclaration();
        AppendNewBlockAndPopulate(builder, mlir_init_declaration_region, [&] {
          VisitDeclaration(builder, std::get<0>(node->init().value()));
        });
        break;
      }
      case 1: {
        mlir::Region &mlir_init_expression_region = op.getInitExpression();
        AppendNewBlockAndPopulate(builder, mlir_init_expression_region, [&] {
          mlir::Value mlir_init_expression = VisitExpression(builder, std::get<1>(node->init().value()));
          CreateStmt<SirExprRegionEndOp>(builder, nullptr, mlir_init_expression);
        });
        break;
      }
      default:
        break;
    }
  }
  switch (node->left().index()) {
    case 0: {
      mlir::Region &mlir_left_declaration_region = op.getLeftDeclaration();
      AppendNewBlockAndPopulate(builder, mlir_left_declaration_region, [&] {
        VisitDeclaration(builder, std::get<0>(node->left()));
      });
      break;
    }
    default:
      break;
  }
  mlir::Region &mlir_body_region = op.getBody();
  AppendNewBlockAndPopulate(builder, mlir_body_region, [&] {
    VisitStatement(builder, node->body());
  });
  return op;
}

SirParenOp AstToSir::VisitParen(mlir::OpBuilder &builder, const SParen *node) {
  mlir::Value mlir_expression = VisitExpression(builder, node->expression());
  return CreateExpr<SirParenOp>(builder, node, mlir_expression);
}

SirParenRefOp AstToSir::VisitParenRef(mlir::OpBuilder &builder, const SParen *node) {
  mlir::Value mlir_expression;
  if (const SPattern *expression_ir = dynamic_cast<const SPattern *>(node->expression())) {
    mlir_expression = VisitPatternRef(builder, expression_ir);
  } else {
    mlir::emitError(builder.getUnknownLoc(), "expression must be a SPattern.");
    mlir_expression = VisitExpression(builder, node->expression());
  }
  return CreateExpr<SirParenRefOp>(builder, node, mlir_expression);
}

SirSpecifierOp AstToSir::VisitSpecifier(mlir::OpBuilder &builder, const SSpecifier *node) {
  mlir::Value mlir_local;
  if (node->local().has_value()) {
    switch (node->local().value().index()) {
      case 0: {
        mlir_local = VisitIdentifierRef(builder, std::get<0>(node->local().value()));
        break;
      }
      case 1: {
        mlir_local = VisitCall(builder, std::get<1>(node->local().value()));
        break;
      }
      default:
        LOG(FATAL) << "Unreachable code.";
    }
  }
  return CreateStmt<SirSpecifierOp>(builder, node, mlir_local);
}

